/**
 * Better Remote Commander (BRC): tool definitions (name, description, JSON schema) vendored from
 * Desktop Commander's server.ts ListTools handler. Generated by scripts/extract-tools.mjs.
 * UI-preview _meta entries removed; descriptions otherwise unchanged.
 */
import { zodToJsonSchema } from 'zod-to-json-schema';
import { getSystemInfo, getOSSpecificGuidance, getPathGuidance } from './utils/system-info.js';
import {
  StartProcessArgsSchema, ReadProcessOutputArgsSchema, InteractWithProcessArgsSchema,
  ForceTerminateArgsSchema, ListSessionsArgsSchema, KillProcessArgsSchema,
  ReadFileArgsSchema, ReadMultipleFilesArgsSchema, WriteFileArgsSchema,
  CreateDirectoryArgsSchema, ListDirectoryArgsSchema, MoveFileArgsSchema,
  PrepareFileTransferArgsSchema, SendFileTransferArgsSchema, ReceiveFileTransferArgsSchema,
  GetFileInfoArgsSchema, GetConfigArgsSchema, SetConfigValueArgsSchema,
  ListProcessesArgsSchema, EditBlockArgsSchema, GetUsageStatsArgsSchema,
  GiveFeedbackArgsSchema, StartSearchArgsSchema, GetMoreSearchResultsArgsSchema,
  StopSearchArgsSchema, ListSearchesArgsSchema, GetPromptsArgsSchema,
  GetRecentToolCallsArgsSchema, WritePdfArgsSchema,
} from './tools/schemas.js';

const CMD_PREFIX_DESCRIPTION = `This command can be referenced as "BRC: ..." or "use Better Remote Commander (BRC) to ..." in your instructions.`;

export interface ToolDefinition {
  name: string;
  description: string;
  inputSchema: unknown;
  annotations?: Record<string, unknown>;
}

/** Upstream-only onboarding/UI tools; never exposed by Better Remote Commander (BRC). */
export const EXCLUDED_TOOLS = new Set(['give_feedback_to_desktop_commander', 'get_prompts', 'track_ui_event']);

export function buildToolDefinitions(): ToolDefinition[] {
  // Computed lazily (not at module load): getSystemInfo() spawns processes.
  const SYSTEM_INFO = getSystemInfo();
  const OS_GUIDANCE = getOSSpecificGuidance(SYSTEM_INFO);
  const PATH_GUIDANCE = `IMPORTANT: ${getPathGuidance(SYSTEM_INFO)} Relative paths may fail as they depend on the current working directory. Tilde paths (~/...) might not work in all contexts. Unless the user explicitly asks for relative paths, use absolute paths.`;
  const allTools: ToolDefinition[] = [
    // Configuration tools
    {
        name: "get_config",
        description: `
                Get the complete server configuration as JSON. Config includes fields for:
                - blockedCommands (array of blocked shell commands)
                - defaultShell (shell to use for commands)
                - allowedDirectories (paths the server can access)
                - fileReadLineLimit (default lines for read_file, default 300; hard max 2000)
                - fileWriteLineLimit (max lines per write_file call, default 1000; hard max 2000, max 1 MiB)
                - telemetryEnabled (boolean for telemetry opt-in/out)
                - currentClient (information about the currently connected MCP client)
                - clientHistory (history of all clients that have connected)
                - version (version of the DesktopCommander)
                - systemInfo (operating system and environment details)
                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(GetConfigArgsSchema),
        annotations: {
            title: "Get Configuration",
            readOnlyHint: true,
        },
    },
    {
        name: "set_config_value",
        description: `
                Set a specific configuration value by key.
                
                WARNING: Should be used in a separate chat from file operations and 
                command execution to prevent security issues.
                
                Config keys include:
                - blockedCommands (array)
                - defaultShell (string)
                - allowedDirectories (array of paths)
                - fileReadLineLimit (number, max lines for read_file)
                - fileWriteLineLimit (number, max lines per write_file call)
                - telemetryEnabled (boolean)
                
                IMPORTANT: Setting allowedDirectories to an empty array ([]) allows full access 
                to the entire file system, regardless of the operating system.
                
                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(SetConfigValueArgsSchema),
        annotations: {
            title: "Set Configuration Value",
            readOnlyHint: false,
            destructiveHint: true,
            openWorldHint: false,
        },
    },

    // Filesystem tools
    {
        name: "read_file",
        description: `
                ONE FILE OR URL ONLY. If you already know 2+ paths, prefer ONE read_multiple_files call, not several read_file calls or Promise.all(read_file). For narrow code snippets across files with hashes use read_code_ranges; mixed independent reads use batch_tools.
                Read path from allowed directories. Use isUrl=true for URLs. offset/length select lines (0-based) for text files, negative offset tails efficiently; default 300 lines on a new install, configurable up to 2000 lines. Model-facing text is capped at 128000 characters with an explicit TRUNCATED notice for huge lines; request narrower ranges or use read_code_file for character offsets. If you need a full-file SHA-256 for safe edits, use read_code_file.
                Supported formats: text; Excel via sheet/range (A1:D100) or rows; PDF as page text/images with page offsets; DOCX outline by default (offset=0), raw XML with nonzero offset for exact edits; raster images as image content (use read_images for optimized previews/contact sheets). Use dedicated tools instead of launching a shell to cat/type files.
                ${PATH_GUIDANCE}
                ${CMD_PREFIX_DESCRIPTION}`,
                inputSchema: zodToJsonSchema(ReadFileArgsSchema),
        annotations: {
            title: "Read File or URL",
            readOnlyHint: true,
            openWorldHint: true,
        },
    },
    {
        name: "read_multiple_files",
        description: `
                PREFERRED FOR 2 OR MORE KNOWN FILE PATHS: read_multiple_files uses ONE MCP call and reads up to 8 files concurrently. Use this instead of repeating read_file, parallel Promise.all(read_file), or batching several identical read_file calls. Read only the files needed; search first when paths are unknown. For many narrow code snippets with hashes, prefer read_code_ranges. For mixed tool types, use batch_tools. For image previews, prefer read_images.

                Returns a bounded combined response: 200 lines per file by default (up to 2000 when requested), at most 48000 text characters per item, 160000 total text characters and 2 MiB combined image data. A TRUNCATED notice means content is incomplete; reread a smaller range. For image-heavy batches prefer read_images.

                Two ways to list files (can be combined):
                - paths: ["/a.ts", "/b.ts"] → read each file from the start (default line limit)
                - files: [{path: "/a.ts", offset: 120, length: 40}, {path: "/b.log", offset: -50}]
                  → per-file line ranges, same offset/length semantics as read_file
                
                Each file's content is returned with its path as a reference.
                Handles text files normally and renders images as viewable content.
                Recognized image types: PNG, JPEG, GIF, WebP.
                
                Failed reads for individual files won't stop the entire operation.
                Only works within allowed directories.
                
                ${PATH_GUIDANCE}
                ${CMD_PREFIX_DESCRIPTION}`,
        // Cross-field 1+ requirement is enforced by Zod at runtime; express it
        // in JSON Schema as well so an LLM never guesses an empty call.
        inputSchema: {
            ...zodToJsonSchema(ReadMultipleFilesArgsSchema),
            anyOf: [
                { required: ["paths"], properties: { paths: { minItems: 1 } } },
                { required: ["files"], properties: { files: { minItems: 1 } } },
            ],
        },
        annotations: {
            title: "Read Multiple Files",
            readOnlyHint: true,
        },
    },
    {
        name: "write_file",
        description: `
                Write or append to file contents.

                IMPORTANT: DO NOT use this tool to create PDF files. Use 'write_pdf' for all PDF creation tasks.
                DO NOT use this tool to edit DOCX files. Use 'edit_block' with old_string/new_string instead.
                To CREATE a new DOCX, use write_file with .docx extension — text content with markdown headings (#, ##, ###) is converted to styled DOCX paragraphs.

                EFFICIENCY: This tool is for one file. For 2+ known UTF-8 file edits, use workspace_batch (hash-checked changes + readback + checks) instead of repeated write_file calls. For one modest file, write the entire content in ONE call; do NOT split ordinary files into arbitrary 25–30-line chunks. Use append only when continuation is genuinely needed. For safer targeted edits use edit_block with an expected SHA-256, or workspace_batch for coordinated changes.

                FORMAT HANDLING (by extension):
                - Text files: String content
                - Excel (.xlsx, .xls, .xlsm): JSON 2D array or {"SheetName": [[...]]}
                  Example: '[["Name","Age"],["Alice",30]]'

                Direct plain-text writes are limited to the configured fileWriteLineLimit (new default: 1000 lines, hard maximum: 2000) and 1 MiB UTF-8 per call. Oversized writes fail BEFORE changing files with WRITE_LINE_LIMIT/WRITE_SIZE_LIMIT. For large new files use mode=rewrite then explicit mode=append chunks; for edits of existing code use hash-checked workspace_batch or edit_block. Existing nonempty files require explicit mode to avoid accidental overwrites.
                Only works within allowed directories.

                ${PATH_GUIDANCE}
                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(WriteFileArgsSchema),
        annotations: {
            title: "Write File",
            readOnlyHint: false,
            destructiveHint: true,
            openWorldHint: false,
        },
    },
    {
        name: "write_pdf",
        description: `
                Create a new PDF file or modify an existing one.

                THIS IS THE ONLY TOOL FOR CREATING AND MODIFYING PDF FILES.

                RULES ABOUT FILENAMES:
                - When creating a new PDF, 'outputPath' MUST be provided and MUST use a new unique filename (e.g., "result_01.pdf", "analysis_2025_01.pdf", etc.).

                MODES:
                1. CREATE NEW PDF:
                   - Pass a markdown string as 'content'.
                   write_pdf(path="doc.pdf", content="# Title\\n\\nBody text...")

                2. MODIFY EXISTING PDF:
                   - Pass array of operations as 'content'.
                   - NEVER overwrite the original file.
                   - ALWAYS provide a new filename in 'outputPath'.
                   - After modifying, show original file path and new file path to user.

                   write_pdf(path="doc.pdf", content=[
                       { type: "delete", pageIndexes: [0, 2] },
                       { type: "insert", pageIndex: 1, markdown: "# New Page" }
                   ])

                OPERATIONS:
                - delete: Remove pages by 0-based index.
                  { type: "delete", pageIndexes: [0, 1, 5] }

                - insert: Add pages at a specific 0-based index.
                  { type: "insert", pageIndex: 0, markdown: "..." }
                  { type: "insert", pageIndex: 5, sourcePdfPath: "/path/to/source.pdf" }

                PAGE BREAKS:
                To force a page break, use this HTML element:
                <div style="page-break-before: always;"></div>
                
                Example:
                "# Page 1\\n\\n<div style=\\"page-break-before: always;\\"></div>\\n\\n# Page 2"

                ADVANCED STYLING:
                HTML/CSS and inline SVG are supported for:
                - Text styling: colors, sizes, alignment, highlights
                - Boxes: borders, backgrounds, padding, rounded corners
                - SVG graphics: charts, diagrams, icons, shapes
                - Images: <img src="/absolute/path/image.jpg" width="300" /> or ![alt](/path/image.jpg)

                Supports standard markdown features including headers, lists, code blocks, tables, and basic formatting.

                Only works within allowed directories.

                ${PATH_GUIDANCE}
                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(WritePdfArgsSchema),
        annotations: {
            title: "Write/Modify PDF",
            readOnlyHint: false,
            destructiveHint: true,
            openWorldHint: false,
        },
    },
    {
        name: "create_directory",
        description: `
                Create a new directory or ensure a directory exists.
                
                Can create multiple nested directories in one operation.
                Only works within allowed directories.
                
                ${PATH_GUIDANCE}
                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(CreateDirectoryArgsSchema),
        annotations: {
            title: "Create Directory",
            readOnlyHint: false,
            destructiveHint: false,
        },
    },
    {
        name: "list_directory",
        description: `
                Get a detailed listing of all files and directories in a specified path.
                
                Use this instead of 'execute_command' with ls/dir commands.
                Results distinguish between files and directories with [FILE] and [DIR] prefixes.
                
                Supports recursive listing with the 'depth' parameter (default: 2):
                - depth=1: Only direct contents of the directory
                - depth=2: Contents plus one level of subdirectories
                - depth=3+: Multiple levels deep
                
                CONTEXT OVERFLOW PROTECTION:
                - Top-level directory shows ALL items
                - Nested directories are limited to 100 items maximum per directory
                - When a nested directory has more than 100 items, you'll see a warning like:
                  [WARNING] node_modules: 500 items hidden (showing first 100 of 600 total)
                - This prevents overwhelming the context with large directories like node_modules
                
                Results show full relative paths from the root directory being listed.
                Example output with depth=2:
                [DIR] src
                [FILE] src/index.ts
                [DIR] src/tools
                [FILE] src/tools/filesystem.ts
                
                If a directory cannot be accessed, it will show [DENIED] instead.
                If a path does not exist, it will show [NOT_FOUND] instead.
                Only works within allowed directories.
                
                ${PATH_GUIDANCE}
                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(ListDirectoryArgsSchema),
        annotations: {
            title: "List Directory Contents",
            readOnlyHint: true,
        },
    },
    {
        name: "move_file",
        description: `
                Move or rename files and directories.
                
                Can move files between directories and rename them in a single operation.
                Both source and destination must be within allowed directories.
                
                ${PATH_GUIDANCE}
                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(MoveFileArgsSchema),
        annotations: {
            title: "Move/Rename File",
            readOnlyHint: false,
            destructiveHint: true,
            openWorldHint: false,
        },
    },
    {
        name: "prepare_file_transfer",
        description: `
                Prepare this device to receive an end-to-end encrypted file from another BRC device.

                CROSS-DEVICE WORKFLOW:
                1. Run prepare_file_transfer on the destination device.
                2. Pass recipientPublicKey to send_file_transfer on the source device.
                3. Pass the returned transferToken plus this receiveId to receive_file_transfer on this destination.

                The private X25519 receive key stays only in this agent's memory and expires automatically.
                The LLM/relay never receives the raw AES file-encryption key.

                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(PrepareFileTransferArgsSchema),
        annotations: {
            title: "Prepare Encrypted File Receive",
            readOnlyHint: false,
            destructiveHint: false,
            openWorldHint: false,
        },
    },
    {
        name: "send_file_transfer",
        description: `
                Encrypt a local file and upload only ciphertext to temporary storage for another BRC device.

                SECURITY:
                - Maximum plaintext size: 99 MB.
                - Uses AES-256-GCM for the file.
                - The AES key is wrapped for the destination's ephemeral X25519 public key.
                - tmpfiles.org receives only a randomly named encrypted blob.
                - The source file is never modified.
                - The returned transferToken contains the download URL and wrapped key material, never the raw AES key.

                Run prepare_file_transfer on the destination first and pass its recipientPublicKey here.

                ${PATH_GUIDANCE}
                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(SendFileTransferArgsSchema),
        annotations: {
            title: "Send Encrypted File Transfer",
            readOnlyHint: false,
            destructiveHint: false,
            openWorldHint: true,
        },
    },
    {
        name: "receive_file_transfer",
        description: `
                Download, authenticate, decrypt, and save a BRC encrypted file transfer on this device.

                Requires receiveId from prepare_file_transfer on this same device and transferToken from
                send_file_transfer on the source device. Data is downloaded only from tmpfiles.org.
                AES-GCM authentication, expected size, and SHA-256 are verified before the destination
                file is committed. Existing files are not replaced unless overwrite=true.

                ${PATH_GUIDANCE}
                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(ReceiveFileTransferArgsSchema),
        annotations: {
            title: "Receive Encrypted File Transfer",
            readOnlyHint: false,
            destructiveHint: true,
            openWorldHint: true,
        },
    },
    {
        name: "start_search",
        description: `
                SEARCH WHEN PATHS ARE UNKNOWN. For filename or content discovery, use ONE start_search call with wait=true and bounded maxResults; avoid unnecessary polling (get_more_search_results) unless you deliberately need streaming.
                searchType="files" finds names; searchType="content" searches file contents. pattern is regex unless literalSearch=true. filePattern filters files; includeHidden and ignoreCase control scope; contextLines adds surrounding lines.
                Choose wait=true for the complete bounded response in one call, wait=false only for a long-running stream. For 2+ known paths, use read_multiple_files instead. For code search with immediate surrounding fresh snippets and hashes, prefer read_code_context.
                Set path to the project directory, narrow pattern/filePattern, and use appropriate limits. Search never edits files.
                ${PATH_GUIDANCE}
                ${CMD_PREFIX_DESCRIPTION}`,
                inputSchema: zodToJsonSchema(StartSearchArgsSchema),
        annotations: {
            title: "Start Search",
            readOnlyHint: true,
        },
    },
    {
        name: "get_more_search_results",
        description: `
                Get more results from an active search with offset-based pagination.
                
                Supports partial result reading with:
                - 'offset' (start result index, default: 0)
                  * Positive: Start from result N (0-based indexing)
                  * Negative: Read last N results from end (tail behavior)
                - 'length' (max results to read, default: 100)
                  * Used with positive offsets for range reading
                  * Ignored when offset is negative (reads all requested tail results)
                
                Examples:
                - offset: 0, length: 100     → First 100 results
                - offset: 200, length: 50    → Results 200-249
                - offset: -20                → Last 20 results
                - offset: -5, length: 10     → Last 5 results (length ignored)
                
                Returns only results in the specified range, along with search status.
                Works like read_process_output - call this repeatedly to get progressive
                results from a search started with start_search.
                
                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(GetMoreSearchResultsArgsSchema),
        annotations: {
            title: "Get Search Results",
            readOnlyHint: true,
        },
    },
    {
        name: "stop_search",
        description: `
                Stop an active search.
                
                Stops the background search process gracefully. Use this when you've found
                what you need or if a search is taking too long. Similar to force_terminate
                for terminal processes.
                
                The search will still be available for reading final results until it's
                automatically cleaned up after 5 minutes.
                
                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(StopSearchArgsSchema),
        annotations: {
            title: "Stop Search",
            readOnlyHint: false,
            destructiveHint: false,
        },
    },
    {
        name: "list_searches",
        description: `
                List all active searches.
                
                Shows search IDs, search types, patterns, status, and runtime.
                Similar to list_sessions for terminal processes. Useful for managing
                multiple concurrent searches.
                
                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(ListSearchesArgsSchema),
        annotations: {
            title: "List Active Searches",
            readOnlyHint: true,
        },
    },
    {
        name: "get_file_info",
        description: `
                Retrieve detailed metadata about a file or directory including:
                - size
                - creation time
                - last modified time
                - permissions
                - type
                - lineCount (for text files)
                - lastLine (zero-indexed number of last line, for text files)
                - appendPosition (line number for appending, for text files)
                - sheets (for Excel files - array of {name, rowCount, colCount})

                Only works within allowed directories.
                
                ${PATH_GUIDANCE}
                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(GetFileInfoArgsSchema),
        annotations: {
            title: "Get File Information",
            readOnlyHint: true,
        },
    },
    // Note: list_allowed_directories removed - use get_config to check allowedDirectories

    // Editing tools
    {
        name: "edit_block",
        description: `
                Apply surgical edits to files.

                BEST PRACTICE: Make multiple small, focused edits rather than one large edit.
                Each edit_block call should change only what needs to be changed - include just enough
                context to uniquely identify the text being modified.

                FORMAT HANDLING (by extension):

                EXCEL FILES (.xlsx, .xls, .xlsm) - Range Update mode:
                Takes:
                - file_path: Path to the Excel file
                - range: ALWAYS use FROM:TO format - "SheetName!A1:C10" or "SheetName!C1:C1"
                - content: 2D array, e.g., [["H1","H2"],["R1","R2"]]

                TEXT FILES - Find/Replace mode:
                Takes:
                - file_path: Path to the file to edit
                - old_string: Text to replace
                - new_string: Replacement text
                - expected_replacements: Optional number of replacements (default: 1)

                DOCX FILES (.docx) - XML Find/Replace mode:
                Takes same parameters as text files (old_string, new_string, expected_replacements).
                Operates on the pretty-printed XML inside the DOCX — the same XML you see from
                read_file with offset/length. Copy XML fragments from read output as old_string.
                After editing, the XML is repacked into a valid DOCX.
                Also searches headers/footers if not found in document body.
                Examples:
                - Replace text: old_string="<w:t>Old Text</w:t>" new_string="<w:t>New Text</w:t>"
                - Change style: old_string='<w:pStyle w:val="Normal"/>' new_string='<w:pStyle w:val="Heading1"/>'
                - Add content: include surrounding XML context in old_string, add new elements in new_string

                By default, replaces only ONE occurrence of the search text.
                To replace multiple occurrences, provide expected_replacements with
                the exact number of matches expected.

                UNIQUENESS REQUIREMENT: When expected_replacements=1 (default), include the minimal
                amount of context necessary (typically 1-3 lines) before and after the change point,
                with exact whitespace and indentation.

                MULTI-EDIT (preferred for several changes in one file):
                Pass edits: [{old_string, new_string, expected_replacements?}, ...] instead of
                old_string/new_string. Edits apply in order (each sees the result of the previous one)
                in ONE call. For text files it is all-or-nothing: if any edit fails to match, nothing
                is written and the failing edit is reported.

                When a close but non-exact match is found, a character-level diff is shown in the format:
                common_prefix{-removed-}{+added+}common_suffix to help you identify what's different.

                edit_block warns about oversized search/replacement blocks. Unlike write_file's strict per-call create/append limit, it operates on existing files using focused exact replacements and atomic publication. Prefer small hash-checked edits and use workspace_batch for large coordinated changes.

                ${PATH_GUIDANCE}
                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(EditBlockArgsSchema),
        annotations: {
            title: "Edit Block",
            readOnlyHint: false,
            destructiveHint: true,
            openWorldHint: false,
        },
    },

    // Terminal tools
    {
        name: "start_process",
        description: `
                RUN COMMANDS OR START PROCESSES ONLY WHEN NEEDED. Use for build/test commands, execution, system inspection, or an operation with no dedicated MCP tool.
                NOT a file-reader shortcut: use read_multiple_files for 2+ known paths, read_file for one path, start_search with wait=true for unknown paths, and batch_tools for independent mixed reads. Do not start a Python/Node REPL just to inspect code.
                Prefer workspace_batch for coordinated code changes and checks; start_process is not part of safe read-only batches.
                ${OS_GUIDANCE}
                The command runs on the connected device, not the relay container. Choose shell syntax for that OS. A command may be destructive; do not run unrequested changes.
                Specify a bounded timeout_ms. Inspect returned output/exit status first. Use read_process_output only when the process is still running, interact_with_process only for a genuine interactive process.
                For performance diagnosis, verbose_timing=true includes timing breakdown. Avoid polling completed commands.
                ${PATH_GUIDANCE}
                ${CMD_PREFIX_DESCRIPTION}`,
                inputSchema: zodToJsonSchema(StartProcessArgsSchema),
        annotations: {
            title: "Start Terminal Process",
            readOnlyHint: false,
            destructiveHint: true,
            openWorldHint: true,
        },
    },
    {
        name: "read_process_output",
        description: `
                Use only for a process started by start_process that is still running; do not poll for commands that already returned their final output. Read output from a running process with file-like pagination support.
                
                Supports partial output reading with offset and length parameters (like read_file):
                - 'offset' (start line, default: 0)
                  * offset=0: Read NEW output since last read (default, like old behavior)
                  * Positive: Read from absolute line position
                  * Negative: Read last N lines from end (tail behavior)
                - 'length' (max lines to read, default: configurable via 'fileReadLineLimit' setting)
                
                Examples:
                - offset: 0, length: 100     → First 100 NEW lines since last read
                - offset: 0                  → All new lines (respects config limit)
                - offset: 500, length: 50    → Lines 500-549 (absolute position)
                - offset: -20                → Last 20 lines (tail)
                - offset: -50, length: 10    → Start 50 from end, read 10 lines
                
                OUTPUT PROTECTION:
                - Uses the configured fileReadLineLimit for process output (new default: 300 lines)
                - Returns status like: [Reading 100 lines from line 0 (total: 5000 lines, 4900 remaining)]
                - Prevents context overflow from verbose processes
                
                SMART FEATURES:
                - For offset=0, waits up to timeout_ms (default 5 seconds) for new output
                - timeout_ms limits only this read wait; it NEVER terminates the process or limits build duration
                - For long-running jobs, repeat reads or use wait_jobs; the process continues in the background
                - Detects REPL prompts and process completion
                - Shows process state (waiting for input, finished, etc.)
                
                DETECTION STATES:
                Process waiting for input (ready for interact_with_process)
                Process finished execution
                Timeout reached (may still be running)

                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(ReadProcessOutputArgsSchema),
        annotations: {
            title: "Read Process Output",
            readOnlyHint: true,
        },
    },
    {
        name: "interact_with_process",
        description: `
                Send input to an ALREADY-RUNNING interactive shell, REPL or process (pid from start_process) and receive new output. Only use when an existing process needs further input; do not use as a default file-reading, search, or editing method.
                For several known files, use read_multiple_files; for source searches use start_search(wait=true), for batched independent reads use batch_tools, for coordinated writes use workspace_batch. This tool adds a process round trip and should not be used for ordinary one-shot file inspection.
                Parameters: pid, input, optional timeout_ms, wait_for_prompt and verbose_timing. Confirm the program is still active and send commands deliberately.
                ${CMD_PREFIX_DESCRIPTION}`,
                inputSchema: zodToJsonSchema(InteractWithProcessArgsSchema),
        annotations: {
            title: "Send Input to Process",
            readOnlyHint: false,
            destructiveHint: true,
            openWorldHint: true,
        },
    },
    {
        name: "force_terminate",
        description: `
                Force terminate a running terminal session.
                
                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(ForceTerminateArgsSchema),
        annotations: {
            title: "Force Terminate Process",
            readOnlyHint: false,
            destructiveHint: true,
            openWorldHint: false,
        },
    },
    {
        name: "list_sessions",
        description: `
                List all active terminal sessions.
                
                Shows session status including:
                - PID: Process identifier  
                - Blocked: Whether session is waiting for input
                - Runtime: How long the session has been running
                
                DEBUGGING REPLs:
                - "Blocked: true" often means REPL is waiting for input
                - Use this to verify sessions are running before sending input
                - Long runtime with blocked status may indicate stuck process
                
                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(ListSessionsArgsSchema),
        annotations: {
            title: "List Terminal Sessions",
            readOnlyHint: true,
        },
    },
    {
        name: "list_processes",
        description: `
                List all running processes.
                
                Returns process information including PID, command name, CPU usage, and memory usage.
                
                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(ListProcessesArgsSchema),
        annotations: {
            title: "List Running Processes",
            readOnlyHint: true,
        },
    },
    {
        name: "kill_process",
        description: `
                Terminate a running process by PID.

                Use with caution as this will forcefully terminate the specified process.

                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(KillProcessArgsSchema),
        annotations: {
            title: "Kill Process",
            readOnlyHint: false,
            destructiveHint: true,
            openWorldHint: false,
        },
    },
    {
        name: "get_usage_stats",
        description: `
                Get usage statistics for debugging and analysis.
                
                Returns summary of tool usage, success/failure rates, and performance metrics.
                
                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(GetUsageStatsArgsSchema),
        annotations: {
            title: "Get Usage Statistics",
            readOnlyHint: true,
        },
    },
    {
        name: "get_recent_tool_calls",
        description: `
                Get recent local tool-call metadata: tool name, timestamp, status and duration.
                Arguments, source code and command output are not stored or returned.
                Uses the bounded activity history (up to 1000 recent metadata events,
                maximum age 48 hours; older diagnostics are removed by maintenance).
                Useful for inspecting execution status and debugging call sequences.
                This is not a source-code or conversation-context archive.

                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(GetRecentToolCallsArgsSchema),
        annotations: {
            title: "Get Recent Tool Calls",
            readOnlyHint: true,
        },
    },
    {
        name: "give_feedback_to_desktop_commander",
        description: `
                Open feedback form in browser to provide feedback about Desktop Commander.
                
                IMPORTANT: This tool simply opens the feedback form - no pre-filling available.
                The user will fill out the form manually in their browser.
                
                WORKFLOW:
                1. When user agrees to give feedback, just call this tool immediately
                2. No need to ask questions or collect information
                3. Tool opens form with only usage statistics pre-filled automatically:
                   - tool_call_count: Number of commands they've made
                   - days_using: How many days they've used Desktop Commander
                   - platform: Their operating system (Mac/Windows/Linux)
                   - client_id: Analytics identifier
                
                All survey questions will be answered directly in the form:
                - Job title and technical comfort level
                - Company URL for industry context
                - Other AI tools they use
                - Desktop Commander's biggest advantage
                - How they typically use it
                - Recommendation likelihood (0-10)
                - User study participation interest
                - Email and any additional feedback
                
                EXAMPLE INTERACTION:
                User: "sure, I'll give feedback"
                Claude: "Perfect! Let me open the feedback form for you."
                [calls tool immediately]
                
                No parameters are needed - just call the tool to open the form.
                
                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(GiveFeedbackArgsSchema),
        annotations: {
            title: "Give Feedback",
            readOnlyHint: false,
            openWorldHint: true,
        },
    },
    {
        name: "get_prompts",
        description: `
                Retrieve a specific Desktop Commander onboarding prompt by ID and execute it.
                
                SIMPLIFIED ONBOARDING V2: This tool only supports direct prompt retrieval.
                The onboarding system presents 5 options as a simple numbered list:
                
                1. Organize my Downloads folder (promptId: 'onb2_01')
                2. Explain a codebase or repository (promptId: 'onb2_02')
                3. Create organized knowledge base (promptId: 'onb2_03')
                4. Analyze a data file (promptId: 'onb2_04')
                5. Check system health and resources (promptId: 'onb2_05')
                
                USAGE:
                When user says "1", "2", "3", "4", or "5" from onboarding:
                - "1" → get_prompts(action='get_prompt', promptId='onb2_01')
                - "2" → get_prompts(action='get_prompt', promptId='onb2_02')
                - "3" → get_prompts(action='get_prompt', promptId='onb2_03')
                - "4" → get_prompts(action='get_prompt', promptId='onb2_04')
                - "5" → get_prompts(action='get_prompt', promptId='onb2_05')
                
                The prompt content will be injected and execution begins immediately.

                ${CMD_PREFIX_DESCRIPTION}`,
        inputSchema: zodToJsonSchema(GetPromptsArgsSchema),
        annotations: {
            title: "Get Prompts",
            readOnlyHint: true,
        },
    }
  ];
  return allTools.filter(t => !EXCLUDED_TOOLS.has(t.name));
}